def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    start = next(((r, c) for r in range(h) for c in range(w)
                  if grid[r][c] == 3), None)
    if start is None:
        return out

    r, c = start
    # Spiral proceeds up, right, down, left; each pair of runs grows by 2.
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    length = 2
    for i in range(40):
        dr, dc = directions[i % 4]
        for _ in range(length):
            r += dr
            c += dc
            if not (0 <= r < h and 0 <= c < w) or out[r][c] == 2:
                return out
            out[r][c] = 3
        if i % 2 == 1:
            length += 2
    return out
